# ---------------------------------------------------------------- cards.py
"""Cards, deck config and a fast pure-Python hand evaluator.

Cards are ints: rank = c // 4 (0 = lowest rank in the deck), suit = c % 4.
The variant is unknown until event day, so everything reads from VARIANT.
Change the dict (or call set_variant) to match what organizers announce.
"""
import random

RANK_CHARS = "23456789TJQKA"
SUIT_CHARS = "cdhs"

VARIANT = {
    "name": "nlhe",
    "hole": 2,             # hole cards per player
    "board": [0, 3, 1, 1],  # cards dealt on preflop/flop/turn/river
    "low_rank": 0,          # 0 = deuce. Short deck (6+) -> 4
    "must_use_hole": None,  # None = best 5 of any. Omaha -> 2 (exactly 2 hole + 3 board)
    "short_deck": False,    # True: flush beats full house, A-6-7-8-9 straight
}


def set_variant(**kw):
    VARIANT.update(kw)


def deck():
    lo = VARIANT["low_rank"]
    return [r * 4 + s for r in range(lo, 13) for s in range(4)]


def parse(s):
    """'AsKd' -> [cards]."""
    s = s.replace(" ", "")
    return [RANK_CHARS.index(s[i]) * 4 + SUIT_CHARS.index(s[i + 1]) for i in range(0, len(s), 2)]


def show(cards):
    return " ".join(RANK_CHARS[c // 4] + SUIT_CHARS[c % 4] for c in cards)


# ---------------------------------------------------------------- evaluator
# Categories (higher is better)
HIGH, PAIR, TWO_PAIR, TRIPS, STRAIGHT, FLUSH, FULL_HOUSE, QUADS, STRAIGHT_FLUSH = range(9)
CAT_NAMES = ["high", "pair", "two_pair", "trips", "straight", "flush", "full_house", "quads", "straight_flush"]


def _straight_high(mask, low_rank):
    """Highest straight top-rank in a 13-bit rank mask, or -1."""
    # wheel: ace plays low. Standard A2345, short deck A6789
    for top in range(12, low_rank + 3, -1):
        m = 0b11111 << (top - 4)
        if mask & m == m:
            return top
    wheel = (1 << 12) | sum(1 << (low_rank + i) for i in range(4))
    if mask & wheel == wheel:
        return low_rank + 3
    return -1


def _pack(cat, ranks):
    v = cat
    for r in ranks[:5]:
        v = (v << 4) | r
    for _ in range(5 - min(5, len(ranks))):
        v <<= 4
    return v


def eval_any(cards):
    """Best 5-card value from 5..7+ cards. Comparable int, higher wins."""
    short = VARIANT["short_deck"]
    low = VARIANT["low_rank"]
    counts = [0] * 13
    suits = [0, 0, 0, 0]
    smask = [0, 0, 0, 0]
    for c in cards:
        r = c >> 2
        s = c & 3
        counts[r] += 1
        suits[s] += 1
        smask[s] |= 1 << r
    flush_suit = -1
    for s in range(4):
        if suits[s] >= 5:
            flush_suit = s
    if flush_suit >= 0:
        sh = _straight_high(smask[flush_suit], low)
        if sh >= 0:
            return _pack(STRAIGHT_FLUSH, [sh]) + ((1 << 41) if short else 0)
    quads = []; trips = []; pairs = []; singles = []
    mask = 0
    for r in range(12, -1, -1):
        n = counts[r]
        if n:
            mask |= 1 << r
            if n == 4: quads.append(r)
            elif n == 3: trips.append(r)
            elif n == 2: pairs.append(r)
            else: singles.append(r)
    if quads:
        q = quads[0]
        k = max([r for r in range(13) if counts[r] and r != q])
        return _pack(QUADS, [q, k])
    fh = None
    if trips and (len(trips) > 1 or pairs):
        t = trips[0]
        p = max(trips[1:] + pairs)
        fh = _pack(FULL_HOUSE, [t, p])
    fl = None
    if flush_suit >= 0:
        fr = [r for r in range(12, -1, -1) if smask[flush_suit] >> r & 1][:5]
        fl = _pack(FLUSH, fr)
    if short:
        if fl: return fl + (1 << 40)  # flush above full house in short deck
        if fh: return fh
    else:
        if fh: return fh
        if fl: return fl
    sh = _straight_high(mask, low)
    if sh >= 0:
        return _pack(STRAIGHT, [sh])
    if trips:
        t = trips[0]
        ks = [r for r in range(12, -1, -1) if counts[r] and r != t][:2]
        return _pack(TRIPS, [t] + ks)
    if len(pairs) >= 2:
        a, b = pairs[0], pairs[1]
        k = max([r for r in range(13) if counts[r] and r != a and r != b])
        return _pack(TWO_PAIR, [a, b, k])
    if pairs:
        p = pairs[0]
        ks = [r for r in range(12, -1, -1) if counts[r] and r != p][:3]
        return _pack(PAIR, [p] + ks)
    return _pack(HIGH, singles[:5])


def category(value):
    v = value >> 20
    return min(v, 8) if v < 16 else 5  # short-deck flush offset folds back to FLUSH


def evaluate(hole, board):
    """Respects Omaha-style 'must use N hole cards' if configured."""
    need = VARIANT["must_use_hole"]
    if not need:
        return eval_any(list(hole) + list(board))
    from itertools import combinations
    best = -1
    for h in combinations(hole, need):
        for b in combinations(board, 5 - need):
            v = eval_any(list(h) + list(b))
            if v > best:
                best = v
    return best


def total_board():
    return sum(VARIANT["board"])


def showdown_equity(hero, opps, board, rng=random, deck_cards=None):
    """One random runout: returns hero share of pot (1, 0, or split)."""
    used = set(hero) | set(board)
    for o in opps:
        used |= set(o)
    rest = [c for c in (deck_cards or deck()) if c not in used]
    need = total_board() - len(board)
    run = list(board) + rng.sample(rest, need)
    hv = evaluate(hero, run)
    best = hv; ties = 1; hero_best = True
    for o in opps:
        v = evaluate(o, run)
        if v > best:
            best = v; hero_best = False; ties = 1
        elif v == best:
            ties += 1
    return (1.0 / ties) if (hero_best and hv == best) else 0.0

# ---------------------------------------------------------------- features.py
"""Hand abstraction: maps a concrete hand to a bucket key in microseconds.

Preflop: suit-isomorphic class (169 classes for 2-card hold'em, generic for more).
Postflop: made-hand class + sub-type + draws + board texture. The equity of each
bucket is learned offline by Monte Carlo (calibrate.py), so the in-game cost is a
hand evaluation plus a dict lookup, well under the 1 ms limit.
"""


def preflop_key(hole):
    ranks = sorted((c >> 2 for c in hole), reverse=True)
    if len(hole) == 2:
        a, b = ranks
        if a == b:
            return RANK_CHARS[a] * 2
        suited = (hole[0] & 3) == (hole[1] & 3)
        return RANK_CHARS[a] + RANK_CHARS[b] + ("s" if suited else "o")
    # generic: ranks + sorted suit-count signature (approximate isomorphism)
    sc = [0, 0, 0, 0]
    for c in hole:
        sc[c & 3] += 1
    sig = "".join(str(x) for x in sorted(sc, reverse=True) if x)
    return "".join(RANK_CHARS[r] for r in ranks) + ":" + sig


def _kick(k):
    return 2 if k >= 11 else (1 if k >= 8 else 0)


def _straight_outs(mask, low):
    outs = 0
    for r in range(low, 13):
        if mask >> r & 1:
            continue
        m = mask | (1 << r)
        for top in range(12, low + 3, -1):
            w = 0b11111 << (top - 4)
            if m & w == w and (w >> r) & 1:
                outs += 1
                break
        else:
            wheel = (1 << 12) | sum(1 << (low + i) for i in range(4))
            if m & wheel == wheel and (wheel >> r) & 1:
                outs += 1
    return outs


def postflop_key(hole, board):
    """Returns (fine_key, coarse_key, cat_key)."""
    street = len(board)  # 3, 4, 5 for hold'em
    v = evaluate(hole, board)
    cat = category(v)
    hr = [c >> 2 for c in hole]
    br = [c >> 2 for c in board]
    bset = sorted(set(br), reverse=True)
    bmax = bset[0]
    r0 = (v >> 16) & 15
    r1 = (v >> 12) & 15
    sub = 0
    if cat == HIGH:
        sub = "o%d" % min(2, sum(1 for r in set(hr) if r > bmax))
    elif cat == PAIR:
        if r0 in br and r0 in hr:
            pos = min(2, bset.index(r0))
            k = max([r for r in hr if r != r0] or [0])
            sub = "p%d_k%d" % (pos, _kick(k))
        elif r0 in br:
            sub = "bp_o%d" % min(2, sum(1 for r in set(hr) if r > bmax))
        else:
            sub = "over" if r0 > bmax else "under%d" % min(2, sum(1 for r in bset if r > r0))
    elif cat == TWO_PAIR:
        n_in = (r0 in hr) + (r1 in hr)
        top_in = r0 in hr
        sub = "h%d%s" % (n_in, "t" if top_in else "")
    elif cat == TRIPS:
        if hr.count(r0) >= 2:
            sub = "set"
        elif r0 in hr:
            sub = "trips_k%d" % _kick(max([r for r in hr if r != r0] or [0]))
        else:
            sub = "board"
    elif cat == FLUSH:
        suit_counts = [0] * 4
        for c in board:
            suit_counts[c & 3] += 1
        fs = max(range(4), key=lambda s: suit_counts[s] + sum(1 for c in hole if c & 3 == s))
        hs = [c >> 2 for c in hole if c & 3 == fs]
        sub = "nut" if hs and max(hs) >= 11 else ("hole" if hs else "board")
    elif cat == STRAIGHT:
        sub = "top" if r0 >= max(br) + 1 else "low"
    # board-plays check on river
    if street >= 5 and v == eval_any(board):
        sub = "plays_board"

    # draws
    fd = 0; sd = 0
    if street < sum(VARIANT["board"]) and cat < FLUSH:
        for s in range(4):
            hcnt = sum(1 for c in hole if c & 3 == s)
            bcnt = sum(1 for c in board if c & 3 == s)
            need_h = VARIANT["must_use_hole"] or 1
            if hcnt >= need_h and hcnt + bcnt >= 4 and bcnt <= 5 - need_h:
                fd = 1
        if cat < STRAIGHT:
            low = VARIANT["low_rank"]
            mask = 0
            for r in hr + br:
                mask |= 1 << r
            bmask = 0
            for r in br:
                bmask |= 1 << r
            outs = _straight_outs(mask, low) - _straight_outs(bmask, low)
            sd = 2 if outs >= 2 else (1 if outs == 1 else 0)

    # board texture
    bpaired = int(len(bset) < len(br))
    sc = [0, 0, 0, 0]
    for c in board:
        sc[c & 3] += 1
    bsuit = min(3, max(sc))
    conn = 0
    for top in range(12, 3, -1):
        conn = max(conn, sum(1 for r in bset if top - 4 <= r <= top))
    bconn = min(3, conn)

    fine = (street, cat, sub, fd, sd, bpaired, bsuit, bconn)
    coarse = (street, cat, sub, fd, sd)
    return fine, coarse, (street, cat)

# ---------------------------------------------------------------- icm.py
"""Independent Chip Model (Malmuth-Harville) with a bitmask DP.

icm(stacks, payouts) -> expected points per player.
P(player i finishes 1st) = s_i / S; then recursively among the rest.
Cost ~ 2^n * n; ~0.05 ms for 6 players, ~0.3 ms for 8 in CPython,
so the agent only calls it when it matters (all-in sized decisions).
"""
from functools import lru_cache


def icm(stacks, payouts):
    n = len(stacks)
    payouts = list(payouts[:n]) + [0.0] * max(0, n - len(payouts))
    total = float(sum(stacks))
    if total <= 0:
        return [0.0] * n
    ev = [0.0] * n
    full = (1 << n) - 1
    prob = {0: 1.0}
    placed_sum = {0: 0.0}
    # process masks in order of popcount (number already placed above)
    frontier = [0]
    for place in range(n):
        nxt = {}
        pay = payouts[place]
        for mask in frontier:
            pm = prob[mask]
            rem = total - placed_sum[mask]
            if rem <= 0:
                continue
            for i in range(n):
                bit = 1 << i
                if mask & bit or stacks[i] <= 0:
                    continue
                p = pm * stacks[i] / rem
                ev[i] += p * pay
                m2 = mask | bit
                if m2 in nxt:
                    prob[m2] += p
                else:
                    nxt[m2] = 1
                    prob[m2] = p
                    placed_sum[m2] = placed_sum[mask] + stacks[i]
        frontier = list(nxt)
        if not frontier:
            break
    return ev


@lru_cache(maxsize=4096)
def icm_cached(stacks, payouts):
    return icm(stacks, payouts)


if __name__ == "__main__":
    import time
    pay = (50, 30, 20, 10, 5, 3, 1, 0)
    st = (5000, 3000, 2000, 1500, 1200, 1000, 800, 500)
    t = time.perf_counter()
    for _ in range(200):
        v = icm(list(st), pay)
    print("8 players: %.3f ms" % ((time.perf_counter() - t) / 200 * 1e3), [round(x, 2) for x in v])
    t = time.perf_counter()
    for _ in range(200):
        v = icm(list(st[:5]), pay)
    print("5 players: %.3f ms" % ((time.perf_counter() - t) / 200 * 1e3), [round(x, 2) for x in v])

# ---------------------------------------------------------------- opponent.py
"""Per-seat opponent model. Bot state resets each table, and opponents are
anonymous, so we learn each seat from scratch over <=200 hands with priors
(Bayesian shrinkage) so early estimates do not swing wildly.
"""


class SeatStats:
    __slots__ = ("hands", "vpip", "pfr", "shove", "bets", "calls", "folds_vs_bet",
                 "faced_bet", "shown_pcts", "shove_pcts", "limp")

    def __init__(self):
        self.hands = 0
        self.vpip = 0; self.pfr = 0; self.shove = 0; self.limp = 0
        self.bets = 0; self.calls = 0
        self.folds_vs_bet = 0; self.faced_bet = 0
        self.shown_pcts = []   # preflop strength percentile of hands shown at showdown
        self.shove_pcts = []   # percentile of hands shown after a preflop all-in

    # --- shrunk estimates -------------------------------------------------
    @staticmethod
    def _est(k, n, prior, w):
        return (k + prior * w) / (n + w)

    def vpip_rate(self):
        return self._est(self.vpip, self.hands, 0.25, 12)

    def pfr_rate(self):
        return self._est(self.pfr, self.hands, 0.15, 12)

    def shove_rate(self):
        return self._est(self.shove, self.hands, 0.03, 15)

    def fold_to_bet(self):
        return self._est(self.folds_vs_bet, self.faced_bet, 0.45, 8)

    def aggression(self):
        """Share of postflop actions that are bets/raises (vs calls)."""
        return self._est(self.bets, self.bets + self.calls, 0.45, 8)

    def raise_range_pct(self):
        """Estimated top-x% (as fraction) of hands this seat raises preflop."""
        x = self.pfr_rate()
        if self.shown_pcts:
            # uniform over top-x has mean x/2 -> mix in evidence from showdowns
            m = 2 * sum(self.shown_pcts) / len(self.shown_pcts)
            k = len(self.shown_pcts)
            x = (x * 4 + m * k) / (4 + k)
        return min(1.0, max(0.02, x))

    def shove_range_pct(self, prior_pct):
        """Shove range; prior from the push/fold equilibrium at that depth."""
        x = prior_pct
        n = self.hands
        if n:
            obs = self.shove / n
            x = (prior_pct * 10 + obs * n) / (10 + n)
        if self.shove_pcts:
            m = min(1.0, 2 * sum(self.shove_pcts) / len(self.shove_pcts))
            k = len(self.shove_pcts)
            x = (x * 3 + m * k) / (3 + k)
        return min(1.0, max(0.02, x))

    def kind(self):
        """Coarse label, handy in logs."""
        if self.hands < 10:
            return "unknown"
        if self.shove_rate() > 0.4:
            return "maniac"
        if self.vpip_rate() > 0.6 and self.aggression() < 0.3:
            return "station"
        if self.vpip_rate() < 0.12:
            return "nit"
        return "reg"


class OpponentModel:
    def __init__(self, n_seats=8):
        self.s = [SeatStats() for _ in range(n_seats)]

    def __getitem__(self, seat):
        return self.s[seat]

    def update_hand(self, history, seats_in_hand, shown, big_blind, pct_lookup, stacks_start):
        """history: list of (seat, street, action, amount_to); shown: {seat: hole}."""
        pre_actions = {}
        shoved = set()
        for seat, street, act, amt in history:
            st = self.s[seat]
            if street == 0:
                if act in ("call", "raise", "allin"):
                    pre_actions.setdefault(seat, set()).add(act)
                if act in ("raise", "allin") and amt >= 0.9 * stacks_start.get(seat, 1e9):
                    shoved.add(seat)
            else:
                if act in ("raise", "bet", "allin"):
                    st.bets += 1
                elif act == "call":
                    st.calls += 1
        # fold-to-bet: an aggressive action followed by this seat's response
        facing = False
        street_now = 0
        for seat, street, act, amt in history:
            if street != street_now:
                facing = False; street_now = street
            if street > 0:
                if act in ("raise", "bet", "allin"):
                    facing = True
                    continue
                if facing and act in ("fold", "call", "raise"):
                    self.s[seat].faced_bet += 1
                    if act == "fold":
                        self.s[seat].folds_vs_bet += 1
        for seat in seats_in_hand:
            st = self.s[seat]
            st.hands += 1
            acts = pre_actions.get(seat, set())
            if acts:
                st.vpip += 1
            if acts & {"raise", "allin"}:
                st.pfr += 1
            if seat in shoved:
                st.shove += 1
        for seat, hole in shown.items():
            pct = pct_lookup(hole)
            if pct is None:
                continue
            if seat in shoved:
                self.s[seat].shove_pcts.append(pct)
            elif seat in pre_actions and "raise" in pre_actions[seat]:
                self.s[seat].shown_pcts.append(pct)

# ---------------------------------------------------------------- agent.py
"""The competition bot. Every decision is table lookups + arithmetic (<1 ms).

Layers (see the strategy doc):
  1. Blueprint tables from Monte Carlo (calibrate.py) and push/fold CFR+ (pushfold_cfr.py)
  2. Rules that turn equity + pot odds into actions, with sizes from a small action set
  3. Tournament layer: ICM-adjusted call/shove thresholds
  4. Per-seat opponent model: widen/tighten ranges, bluff only seats that fold
"""
import gc, os, pickle, random, time


HERE = os.path.dirname(os.path.abspath(__file__))
TOP_X = (2, 5, 8, 12, 16, 20, 25, 30, 40, 50, 65, 80, 100)
POST_NS = (1, 2, 3, 5)

# --- knobs worth tuning on the day ----------------------------------------
PUSH_FOLD_BB = 10          # at or below this effective depth, unopened pots are shove-or-fold
OPEN_PCT = {1: 0.48, 2: 0.42, 3: 0.30, 4: 0.24, 5: 0.20, 6: 0.17, 7: 0.14}  # by players left to act
OPEN_SIZE_BB = 2.5
VALUE_EQ_HU = 0.62         # postflop value-bet equity threshold heads-up
RAISE_EQ = 0.74            # postflop raise-for-value threshold vs a bet
ICM_MAX_PLAYERS = 6        # exact ICM only when <= this many alive (speed)
ICM_FROM_HAND = 0          # use ICM only from this hand on (or when <= 3 remain). With a skill
                           # edge, chips early are worth more than ICM says; tune with ablate.py
TIME_BUDGET = 0.0006       # seconds; above this skip optional work


def _load(name):
    return _pickle.loads(_zlib.decompress(_b64.b64decode(_BLOBS[name])))


class Agent:
    def __init__(self, seed=0):
        t = _load("tables.pkl")
        self.pre_eq = t["pre_eq"]; self.pct = t["pre_pct"]; self.vs_top = t["pre_vs_top"]
        self.post_eq = t["post_eq"]; self.post_n = t["post_n"]
        try:
            pf = _load("pushfold.pkl")
        except FileNotFoundError:
            pf = None
        self.pf = pf
        self.rng = random.Random(seed)
        self.opp = OpponentModel(8)
        self.seat = None
        self.max_dt = 0.0
        # the big lookup tables are permanent: move them out of the GC's view so a
        # collection cannot stall a decision past the 1 ms limit
        gc.collect(); gc.freeze()

    # ------------------------------------------------------------ lifecycle
    def new_table(self, seat, n_seats):
        self.opp = OpponentModel(n_seats)
        self.seat = seat

    def on_hand_end(self, info):
        gc.collect(0)  # pay for young-gen GC between hands, not inside act()
        self.opp.update_hand(info["history"], info["seats_in_hand"], info["shown"], info["bb"],
                             lambda h: self.pct.get(preflop_key(h)), info["stacks_start"])

    def act(self, o):
        t0 = time.perf_counter()
        self._t0 = t0
        try:
            a = self._act(o)
        except Exception:
            a = ("check", 0) if "check" in o["legal"] else ("fold", 0)
        dt = time.perf_counter() - t0
        if dt > self.max_dt:
            self.max_dt = dt
        return a

    # ------------------------------------------------------------ helpers
    def _late(self):
        return time.perf_counter() - self._t0 > TIME_BUDGET

    @staticmethod
    def _icm_on(o, n_alive):
        return o["hand_no"] >= ICM_FROM_HAND or n_alive <= 3

    def _vs_top(self, key, x):
        x100 = x * 100
        for g in TOP_X:
            if g >= x100:
                return self.vs_top[g].get(key, 0.5)
        return self.vs_top[100].get(key, 0.5)

    def _post_eq(self, hole, board, n):
        fine, coarse, catk = postflop_key(hole, board)
        k = fine if self.post_n.get(fine, 0) >= 40 else (coarse if self.post_n.get(coarse, 0) >= 30 else catk)
        def get(m):
            return self.post_eq[m].get(k, self.post_eq[m].get(catk, 0.3))
        if n in POST_NS:
            eq = get(n)
        elif n == 4:
            eq = 0.5 * (get(3) + get(5))
        else:
            eq = get(5) ** (n / 5.0)
        return eq, fine

    @staticmethod
    def _order(o):
        n = len(o["stacks"])
        alive = [i for i in range(n) if o["alive"][i]]
        b = o["button"]
        order = [(b + k) % n for k in range(1, n + 1)]
        order = [i for i in order if i in alive]
        if len(alive) == 2:
            sbs, bbs = b, [i for i in alive if i != b][0]
            pre = [b, bbs]
        else:
            sbs, bbs = order[0], order[1]
            pre = order[2:] + order[:2]
        return pre, sbs, bbs

    def _icm_required(self, o, villain, risk, pot):
        """Equity needed to call off `risk` chips vs `villain` for a pot of `pot` (ICM)."""
        n_alive = sum(o["alive"])
        chip_req = risk / (pot + risk)
        me = o["seat"]
        if n_alive > ICM_MAX_PLAYERS or self._late() or not self._icm_on(o, n_alive):
            stacks = [s + b for s, b in zip(o["stacks"], o["bets"]) if s + b > 0]
            avg = sum(stacks) / max(1, len(stacks))
            prem = 0.0 if n_alive <= 2 else min(0.06, 0.025 * risk / max(1, avg))
            return min(0.99, chip_req + prem)
        ids = [i for i in range(len(o["stacks"])) if o["alive"][i]]
        base = [o["stacks"][i] for i in ids]
        mi = ids.index(me); vi = ids.index(villain) if villain in ids else None
        pay = o["points"][:n_alive]

        def ev(hero_delta, vil_delta):
            s = list(base)
            s[mi] += hero_delta
            if vi is not None:
                s[vi] += vil_delta
            s = [max(0, x) for x in s]
            return icm(s, pay)[mi]
        e_fold = ev(0, pot)
        e_win = ev(pot, 0)
        e_lose = ev(-risk, pot + risk)
        if e_win - e_lose <= 1e-9:
            return chip_req
        return min(0.99, max(0.0, (e_fold - e_lose) / (e_win - e_lose)))

    def _raise(self, o, to):
        to = int(max(o["min_raise_to"], min(o["max_raise_to"], to)))
        # if the raise leaves us with < 30% of it behind, just shove
        if o["max_raise_to"] - to < 0.3 * to:
            to = o["max_raise_to"]
        return ("raise", to)

    @staticmethod
    def _passive(o):
        return ("check", 0) if "check" in o["legal"] else ("fold", 0)

    # ------------------------------------------------------------ decision
    def _act(self, o):
        if o["street"] == 0:
            return self._preflop(o)
        return self._postflop(o)

    def _preflop(self, o):
        me = o["seat"]; bb = o["bb"]
        hole = o["hole"]; key = preflop_key(hole)
        pct = self.pct.get(key, 0.5)
        pre, sbs, bbs = self._order(o)
        hist = [h for h in o["history"] if h[1] == 0]
        raises = [h for h in hist if h[2] in ("raise", "allin") and h[3] > bb]
        limpers = [h for h in hist if h[2] == "call" and h[3] <= bb]
        others = [i for i in range(len(o["stacks"])) if i != me and o["in_hand"][i]]
        my_total = o["stacks"][me] + o["bets"][me]
        eff = min(my_total, max(o["stacks"][i] + o["bets"][i] for i in others)) if others else my_total
        eff_bb = eff / bb
        idx = pre.index(me) if me in pre else 0
        behind = [i for i in pre[idx + 1:] if o["in_hand"][i] and not o["allin"][i]]

        # ---------------- unopened (maybe limpers)
        if not raises:
            if eff_bb <= PUSH_FOLD_BB and "raise" in o["legal"]:
                return self._shove_or_fold(o, key, pct, behind, eff_bb)
            if "raise" in o["legal"]:
                k = max(1, len(behind))
                thr = OPEN_PCT.get(k, 0.14)
                if behind:
                    v = sum(self.opp[i].vpip_rate() for i in behind) / len(behind)
                    if v < 0.18: thr *= 1.3      # they fold too much: steal wider
                    elif v > 0.5: thr *= 0.75    # they call everything: value only
                if limpers:
                    thr *= 0.6
                if pct <= thr:
                    size = OPEN_SIZE_BB + len(limpers) + (0.5 if me == sbs else 0)
                    return self._raise(o, size * bb)
            return self._passive(o)

        # ---------------- facing a raise
        aggr = raises[-1][0]
        st = self.opp[aggr]
        aggr_total = o["bets"][aggr] + o["stacks"][aggr]
        aggr_shove = o["allin"][aggr] or o["bets"][aggr] >= 0.9 * aggr_total
        if aggr_shove:
            S = min(30.0, max(1.0, round(2 * o["bets"][aggr] / bb) / 2))
            prior = self.pf["push_freq"][S] if self.pf else 0.3
            if o["bets"][aggr] / bb > 30:
                prior = 0.08  # deep shoves from a balanced player are tight
            if len(pre) > 2 and aggr not in (sbs,):
                prior *= 0.7   # earlier-position shoves are tighter
            x = st.shove_range_pct(prior)
        else:
            x = st.raise_range_pct()
        x *= 0.45 ** (len(raises) - 1)
        x = max(0.02, x)
        eq = self._vs_top(key, x)
        n_in = len(others)
        if n_in > 1:
            eq *= 0.85 ** (n_in - 1)
        to_call = o["to_call"]; pot = o["pot"]
        behind_me = o["stacks"][me]
        commit = to_call >= 0.4 * behind_me or aggr_shove

        if commit:
            req = self._icm_required(o, aggr, to_call, pot)
            if eq >= req:
                if "raise" in o["legal"] and not aggr_shove:
                    return ("raise", o["max_raise_to"])
                return ("call", 0)
            return self._passive(o)

        # normal-sized raise, deep stacks
        if (eq >= 0.60 or pct <= 0.02) and "raise" in o["legal"]:
            to = o["current_bet"] * 3 + sum(1 for h in hist if h[2] == "call") * o["current_bet"]
            return self._raise(o, to)
        in_pos = me == o["button"]
        realize = 0.9 if in_pos else 0.75
        if eq * realize * (pot + to_call) - to_call > 0 and to_call <= 0.15 * behind_me and eff_bb >= 15:
            return ("call", 0)
        return self._passive(o)

    def _shove_or_fold(self, o, key, pct, behind, eff_bb):
        me = o["seat"]; bb = o["bb"]
        pot = o["pot"]; my_in = o["bets"][me]; h = o["stacks"][me]
        if not behind:
            return ("check", 0) if "check" in o["legal"] else ("raise", o["max_raise_to"])
        p_nocall = 1.0
        best_v = behind[0]; best_c = -1
        x_call = 0.2
        for i in behind:
            si = min(h + my_in, o["stacks"][i] + o["bets"][i]) / bb
            S = min(30.0, max(1.0, round(2 * si) / 2))
            base_c = self.pf["call_freq"][S] if self.pf else 0.25
            st = self.opp[i]
            if st.shove_rate() > 0.4:
                c = 0.9
            else:
                c = min(0.95, base_c * (st.vpip_rate() / 0.25) ** 0.5)
            p_nocall *= (1 - c)
            if c > best_c:
                best_c = c; best_v = i; x_call = c
        eq = self._vs_top(key, x_call)
        if len(behind) > 2:
            eq *= 0.97
        steal = pot  # relative to folding: hero's posted blind is already in the pot
        vstack = o["stacks"][best_v]
        c_amt = min(h, vstack + o["bets"][best_v] - o["bets"][best_v])
        n_alive = sum(o["alive"])
        if n_alive <= ICM_MAX_PLAYERS and not self._late() and self._icm_on(o, n_alive):
            ids = [i for i in range(len(o["stacks"])) if o["alive"][i]]
            base = [o["stacks"][i] for i in ids]
            mi = ids.index(me); vi = ids.index(best_v)
            pay = o["points"][:n_alive]

            def ev(hd, vd):
                s = list(base); s[mi] += hd; s[vi] += vd
                return icm([max(0, x) for x in s], pay)[mi]
            e_fold = ev(0, 0)
            e_steal = ev(steal, 0)
            e_win = ev(steal + c_amt, -c_amt)
            e_lose = ev(-c_amt, steal + c_amt)
            e_push = p_nocall * e_steal + (1 - p_nocall) * (eq * e_win + (1 - eq) * e_lose)
            good = e_push > e_fold
        else:
            chip = p_nocall * steal + (1 - p_nocall) * (eq * (steal + c_amt) - (1 - eq) * c_amt)
            good = chip > 0.02 * c_amt  # small risk premium without exact ICM
        if good:
            return ("raise", o["max_raise_to"])
        return self._passive(o)

    def _postflop(self, o):
        me = o["seat"]; bb = o["bb"]
        hole = o["hole"]; board = o["board"]
        others = [i for i in range(len(o["stacks"])) if i != me and o["in_hand"][i]]
        n = max(1, len(others))
        eq, fine = self._post_eq(hole, board, n)
        street, cat, sub, fd, sd, bpaired, bsuit, bconn = fine
        last_street = len(board) >= 5
        # opponents who stayed in are stronger than random; tighter players more so
        v = sum(self.opp[i].vpip_rate() for i in others) / n
        eq -= 0.06 * (1 - v)
        pot = o["pot"]; to_call = o["to_call"]; h = o["stacks"][me]
        legal = o["legal"]
        draw = (fd or sd == 2) and not last_street

        if to_call > 0:
            bettor = max(others, key=lambda i: o["bets"][i])
            agg = self.opp[bettor].aggression()
            bet_frac = to_call / max(1, pot - to_call)
            disc = (0.08 + 0.05 * (street - 3)) * min(1.5, bet_frac) * max(0.2, 1.2 - agg)
            eqf = eq - disc
            if draw:
                eqf += 0.04
            commit = to_call >= 0.45 * h or o["allin"][bettor]
            if commit:
                req = self._icm_required(o, bettor, to_call, pot)
                if eqf >= req:
                    return ("call", 0) if "call" in legal else ("raise", o["max_raise_to"])
                return self._passive(o)
            if eqf >= RAISE_EQ and "raise" in legal and self.rng.random() < 0.8:
                return self._raise(o, o["current_bet"] + 0.8 * (pot + to_call))
            req = to_call / (pot + to_call)
            if eqf >= req:
                return ("call", 0)
            return self._passive(o)

        # checked to us / first to act
        v_th = VALUE_EQ_HU / (1 + 0.25 * (n - 1))
        wet = bsuit >= 2 and bconn >= 3
        frac = 0.75 if wet else 0.6
        if "raise" not in legal:
            return ("check", 0)
        if eq >= v_th:
            size = frac * pot
            if h <= 1.3 * pot:
                return ("raise", o["max_raise_to"])
            return self._raise(o, o["current_bet"] + max(bb, size))
        if draw and self.rng.random() < 0.55:
            return self._raise(o, o["current_bet"] + max(bb, 0.6 * pot))
        # bluff seats that fold: HU only, never versus stations
        if n == 1:
            ftb = self.opp[others[0]].fold_to_bet()
            p_bluff = 0.0
            if ftb > 0.5:
                p_bluff = min(0.7, (ftb - 0.4) * 1.5)
            elif ftb > 0.4:
                p_bluff = 0.15
            if cat == 0 and self.rng.random() < p_bluff:
                return self._raise(o, o["current_bet"] + max(bb, 0.5 * pot))
        return ("check", 0)


# ============================================================ ADAPTER (edit on the day)
# Map the starter kit's observation object to the dict Agent.act() expects:
#   hole, board (card ints, rank*4+suit, rank 0=2..12=A, suit 0..3 = c,d,h,s), street (0..3),
#   seat, button, sb, bb, stacks (chips behind, per seat), bets (this street, per seat),
#   in_hand, allin, alive (bools per seat), pot (incl. current bets), to_call, current_bet,
#   min_raise_to, max_raise_to, legal (subset of fold/check/call/raise),
#   history [(seat, street, action, amount_to)], hand_no, points (per finishing place, 1st first)
_BOT = None
def _bot():
    global _BOT
    if _BOT is None:
        _BOT = Agent(seed=1)
    return _BOT
